Item.method_code:
const { getState, favorites, rows, getProps } = options;
const { grid } = getState();
const selectedRows = grid.selectedRows;
const relatedId = rows.get(selectedRows[0], 'related_id');
const configId = rows.get(relatedId, 'config_id');
const props = getProps();
const selectedFavorite = favorites.filterFavorites(
	props.favorites,
	'Item',
	({ additional_data: additionalData }) => additionalData.id === configId
)[0];

if (selectedFavorite) {
	const { openFavoriteDialog } = aras.getMainWindow().ArasCore.Dialogs;
	return openFavoriteDialog(selectedFavorite);
}
